// Some portions generated by Codex

/** Server identity comes from the repository manager selected by the backend, never from a browser cookie. */
export function repositoryScope(basePath: string, repositoryId: string, serverIdentity: string): string {
  if (!serverIdentity) throw new Error("The repository server identity is unavailable.");
  return JSON.stringify(["repository-v2", basePath.replace(/\/+$/, ""), serverIdentity, repositoryId]);
}
